-- ==============================================================================
-- TRADE CARS -- Importa el historico de COMPRAS (16/09/2026)
--
-- Fuente: hoja "COMPRAS" de "OP TDC 2024 - Jean Marcos Silvera Pantoja.xlsx".
-- 1307 filas reales, 113 columnas (TODAS las de la hoja --
-- pedido explicito -- salvo 2 columnas separadoras vacias del Excel).
--
-- La hoja tiene un bloque secundario de columnas (a partir de "N COMPRA")
-- que repite nombres del bloque principal (MARCA, MODELO, VALOR DE COMPRA...)
-- -- es un resumen/valorizado de stock incrustado a la derecha de la misma
-- hoja. Se importa tambien, con sufijo _2 en el nombre de columna cuando el
-- nombre ya existia en el bloque principal, para no perder ningun dato.
--
-- Nombres de columna generados mecanicamente desde el encabezado de Excel
-- (minusculas, sin tildes, no-alfanumerico -> "_"), en el MISMO ORDEN que
-- las columnas de la hoja. Mapeo completo header original -> columna SQL:
--   'FECHA DE COMPRA' -> fecha_de_compra
--   'CUENTA' -> cuenta
--   'PLACA' -> placa
--   'CONCAT' -> concat
--   'MARCA' -> marca
--   'MODELO' -> modelo
--   'VERSIÓN' -> version
--   'COLOR' -> color
--   'AÑO' -> ano
--   'TIPO DE COMBUSTIBLE' -> tipo_de_combustible
--   'TRANSMISIÓN' -> transmision
--   'KILOMETRAJE' -> kilometraje
--   'TIPO DE VEHICULO' -> tipo_de_vehiculo
--   'CANAL DE COMPRA' -> canal_de_compra
--   'ASESOR COMERCIAL / COMPRADOR' -> asesor_comercial_comprador
--   'DETALLE CANAL DE COMPRA' -> detalle_canal_de_compra
--   'NOMBRE REFERIDO COMPRA' -> nombre_referido_compra
--   'TIPO (COMPRA / RETOMA)' -> tipo_compra_retoma
--   'TIPO DE COMPRA' -> tipo_de_compra
--   'PRECIO DE COMPRA / VALOR ACTA' -> precio_de_compra_valor_acta
--   'VALOR DE COMPRA' -> valor_de_compra
--   'COMISION - REFERIDO' -> comision_referido
--   'NOTARIALES' -> notariales
--   'IMPUESTO VEHICULAR' -> impuesto_vehicular
--   'SOAT' -> soat
--   'RTV' -> rtv
--   'MULTA SAT' -> multa_sat
--   'MULTA CALLAO' -> multa_callao
--   'MULTA SUTRAN' -> multa_sutran
--   'LEVANTAMIENTO DE PRENDA' -> levantamiento_de_prenda
--   'OTROS GASTOS DOCUMENTALES' -> otros_gastos_documentales
--   'DETALLE DE OTROS GASTOS DOCUMENTALES' -> detalle_de_otros_gastos_documentales
--   'ARREGLOS ESTETICOS' -> arreglos_esteticos
--   'ARREGLOS MECANICOS' -> arreglos_mecanicos
--   'LAVADO DE SALON' -> lavado_de_salon
--   'TRATAMIENTO DE PINTURA' -> tratamiento_de_pintura
--   'DETALLE ARREGLOS' -> detalle_arreglos
--   'TOTAL GASTOS EXTRAS PROV' -> total_gastos_extras_prov
--   'COSTO TOTAL + TOTAL PROVISIÓN' -> costo_total_total_provision
--   'IMPUESTO VEHICULAR PROV' -> impuesto_vehicular_prov
--   'SOAT.' -> soat_2
--   'RTV.' -> rtv_2
--   'MULTA SAT.' -> multa_sat_2
--   'MULTA CALLAO.' -> multa_callao_2
--   'MULTA SUTRAN.' -> multa_sutran_2
--   'LEVANTAMIENTO DE PRENDA.' -> levantamiento_de_prenda_2
--   'OTROS GASTOS DOCUMENTALES.' -> otros_gastos_documentales_2
--   'ARREGLOS ESTETICOS.' -> arreglos_esteticos_2
--   'ARREGLOS MECANICOS.' -> arreglos_mecanicos_2
--   'LAVADO DE SALON.' -> lavado_de_salon_2
--   'TRATAMIENTO DE PINTURA.' -> tratamiento_de_pintura_2
--   'OTROS GASTOS' -> otros_gastos
--   'TOTAL GASTOS EXTRAS REALES' -> total_gastos_extras_reales
--   'COSTO TOTAL + GASTOS EXTRAS REAL' -> costo_total_gastos_extras_real
--   'COSTO TOTAL SIN IGV' -> costo_total_sin_igv
--   'NOTARIA' -> notaria
--   'COMPRA - PRENDA / STATUS' -> compra_prenda_status
--   'BANCO PRENDA' -> banco_prenda
--   'STATUS NOTARIAL' -> status_notarial
--   'DECLARACION JURADA' -> declaracion_jurada
--   'PAGADO' -> pagado
--   'CUENTA DE' -> cuenta_de
--   'DETALLE DE OPERACIÓN' -> detalle_de_operacion
--   'REGISTRO STOCK' -> registro_stock
--   'VENCIMIENTO SOAT' -> vencimiento_soat
--   'DIAS' -> dias
--   'RTV' -> rtv_3
--   'VENCIMIENTO DE RTV' -> vencimiento_de_rtv
--   'CERTIFICADO DE GAS' -> certificado_de_gas
--   'OTROS DOCUMENTOS' -> otros_documentos
--   'STATUS' -> status
--   'RANGO DE INV.' -> rango_de_inv
--   'VIN' -> vin
--   'MOTOR' -> motor
--   'FECHA COMPRA' -> fecha_compra
--   'FECHA VENTA' -> fecha_venta
--   'Tramitador de prenda' -> tramitador_de_prenda
--   'PLACA II' -> placa_ii
--   'COSTO TOTAL  REAL + TOTAL PROVISIÓN' -> costo_total_real_total_provision
--   'COSTO TOTAL + GASTOS EXTRAS REAL' -> costo_total_gastos_extras_real_2
--   'STATUS II' -> status_ii
--   'N° COMPRA' -> n_compra
--   'KARDEX' -> kardex
--   'A NOMBRE DE ' -> a_nombre_de
--   'SEMANA' -> semana
--   'PLACA III' -> placa_iii
--   'MARCA' -> marca_2
--   'MODELO' -> modelo_2
--   'PRECIO' -> precio
--   'PRECIO DE CIERRE' -> precio_de_cierre
--   'VERSION' -> version_2
--   'AÑO FAB' -> ano_fab
--   'KM' -> km
--   'COLOR' -> color_2
--   'TIPO DE VEHICULO' -> tipo_de_vehiculo_2
--   'COMBUSTIBLE' -> combustible
--   'TRANSMISIÓN' -> transmision_2
--   'FECHA DE COMPRA' -> fecha_de_compra_2
--   'TIPO (COMPRA / RETOMA)' -> tipo_compra_retoma_2
--   'TIPO DE COMPRA' -> tipo_de_compra_2
--   'VALOR DE COMPRA' -> valor_de_compra_2
--   'IGV COMPRA' -> igv_compra
--   'ADQUISICION' -> adquisicion
--   'COMISIÓN COMPRA' -> comision_compra
--   'COMISION VENTA' -> comision_venta
--   'GASTOS EXTRAS' -> gastos_extras
--   'COSTO TOTAL' -> costo_total
--   'NOTARIALES' -> notariales_2
--   'COSTO TOTAL + NOTARIALES' -> costo_total_notariales
--   'A NOMBRE DE' -> a_nombre_de_2
--   'DIAS DE INV.' -> dias_de_inv
--   'DISPONIBLE PARA VENTA' -> disponible_para_venta
--   'STATUS II' -> status_ii_2
--
-- Tipo por columna inferido de los datos reales (DATE si todas las celdas no
-- vacias son fecha, NUMERIC si todas son numero, TEXT en cualquier otro caso).
--
-- Idempotente: UPSERT por "concat" (PLACA + numero de operacion, como ya usa
-- tradecars_data_historico_compras_ventas), asi se puede volver a correr sin
-- duplicar filas.
-- ==============================================================================

CREATE TABLE IF NOT EXISTS public.tradecars_data_historico_compras (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  fecha_de_compra DATE,
  cuenta NUMERIC,
  placa TEXT,
  concat TEXT,
  marca TEXT,
  modelo TEXT,
  version TEXT,
  color TEXT,
  ano TEXT,
  tipo_de_combustible TEXT,
  transmision TEXT,
  kilometraje NUMERIC,
  tipo_de_vehiculo TEXT,
  canal_de_compra TEXT,
  asesor_comercial_comprador TEXT,
  detalle_canal_de_compra TEXT,
  nombre_referido_compra TEXT,
  tipo_compra_retoma TEXT,
  tipo_de_compra TEXT,
  precio_de_compra_valor_acta NUMERIC,
  valor_de_compra NUMERIC,
  comision_referido NUMERIC,
  notariales NUMERIC,
  impuesto_vehicular NUMERIC,
  soat TEXT,
  rtv TEXT,
  multa_sat NUMERIC,
  multa_callao NUMERIC,
  multa_sutran NUMERIC,
  levantamiento_de_prenda NUMERIC,
  otros_gastos_documentales NUMERIC,
  detalle_de_otros_gastos_documentales TEXT,
  arreglos_esteticos NUMERIC,
  arreglos_mecanicos NUMERIC,
  lavado_de_salon NUMERIC,
  tratamiento_de_pintura NUMERIC,
  detalle_arreglos TEXT,
  total_gastos_extras_prov NUMERIC,
  costo_total_total_provision NUMERIC,
  impuesto_vehicular_prov NUMERIC,
  soat_2 TEXT,
  rtv_2 NUMERIC,
  multa_sat_2 NUMERIC,
  multa_callao_2 NUMERIC,
  multa_sutran_2 NUMERIC,
  levantamiento_de_prenda_2 NUMERIC,
  otros_gastos_documentales_2 NUMERIC,
  arreglos_esteticos_2 NUMERIC,
  arreglos_mecanicos_2 NUMERIC,
  lavado_de_salon_2 NUMERIC,
  tratamiento_de_pintura_2 NUMERIC,
  otros_gastos NUMERIC,
  total_gastos_extras_reales NUMERIC,
  costo_total_gastos_extras_real NUMERIC,
  costo_total_sin_igv NUMERIC,
  notaria TEXT,
  compra_prenda_status TEXT,
  banco_prenda TEXT,
  status_notarial TEXT,
  declaracion_jurada TEXT,
  pagado TEXT,
  cuenta_de TEXT,
  detalle_de_operacion TEXT,
  registro_stock TEXT,
  vencimiento_soat TEXT,
  dias TEXT,
  rtv_3 TEXT,
  vencimiento_de_rtv TEXT,
  certificado_de_gas TEXT,
  otros_documentos TEXT,
  status TEXT,
  rango_de_inv TEXT,
  vin TEXT,
  motor TEXT,
  fecha_compra DATE,
  fecha_venta TEXT,
  tramitador_de_prenda TEXT,
  placa_ii TEXT,
  costo_total_real_total_provision NUMERIC,
  costo_total_gastos_extras_real_2 NUMERIC,
  status_ii TEXT,
  n_compra NUMERIC,
  kardex TEXT,
  a_nombre_de TEXT,
  semana TEXT,
  placa_iii TEXT,
  marca_2 TEXT,
  modelo_2 TEXT,
  precio NUMERIC,
  precio_de_cierre NUMERIC,
  version_2 TEXT,
  ano_fab TEXT,
  km NUMERIC,
  color_2 TEXT,
  tipo_de_vehiculo_2 TEXT,
  combustible TEXT,
  transmision_2 TEXT,
  fecha_de_compra_2 DATE,
  tipo_compra_retoma_2 TEXT,
  tipo_de_compra_2 TEXT,
  valor_de_compra_2 NUMERIC,
  igv_compra NUMERIC,
  adquisicion NUMERIC,
  comision_compra NUMERIC,
  comision_venta NUMERIC,
  gastos_extras NUMERIC,
  costo_total NUMERIC,
  notariales_2 NUMERIC,
  costo_total_notariales NUMERIC,
  a_nombre_de_2 TEXT,
  dias_de_inv NUMERIC,
  disponible_para_venta TEXT,
  status_ii_2 TEXT,
  sheet_row_id TEXT,
  import_batch_id TEXT,
  sincronizado_en TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  actualizado_en TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now()),
  actualizado_por TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc', now())
);

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'tradecars_data_historico_compras_concat_key'
  ) THEN
    ALTER TABLE public.tradecars_data_historico_compras
      ADD CONSTRAINT tradecars_data_historico_compras_concat_key UNIQUE (concat);
  END IF;
END $$;

-- Sin policy para `anon` a proposito -- mismo criterio que
-- tradecars_data_historico_compras_ventas (precios de compra reales, no se
-- exponen al navegador sin pasar por el servidor).
ALTER TABLE public.tradecars_data_historico_compras ENABLE ROW LEVEL SECURITY;

